from fractions import Fraction
def ins(a):
    a=list(a); c=0
    for i in range(1,len(a)):
        j=i
        while j>0:
            c+=1
            if a[j-1]>a[j]: a[j-1],a[j]=a[j],a[j-1]; j-=1
            else: break
    return c
