def sqmul(x,n):
    k=n.bit_length()-1; pw=[x]; m=0
    for _ in range(k): pw.append(pw[-1]*pw[-1]); m+=1
    r=None
    for j in range(k+1):
        if n>>j&1:
            if r is None: r=pw[j]
            else: r=r*pw[j]; m+=1
    return r,m
r,m=sqmul(3,13); assert r==1594323==3**13 and m==5
for n in range(1,5001):
    r,m=sqmul(2,n); assert r==2**n and m<=2*(n.bit_length()-1)

