# reviewer: minimal DFA sizes by subset construction + Moore partition refinement
import itertools
def minimal_size(start,step,acc,alpha):
    seen=[start]; idx={start:0}; i=0
    while i<len(seen):
        for a in alpha:
            t=step(seen[i],a)
            if t not in idx: idx[t]=len(seen); seen.append(t)
        i+=1
    part={s:acc(s) for s in seen}
    while True:
        sig={s:(part[s],)+tuple(part[step(s,a)] for a in alpha) for s in seen}
        if len(set(sig.values()))==len(set(part.values())): return len(set(part.values()))
        part=sig
# k-th symbol from the end is 1: NFA with k+1 states; subset DFA minimal size 2^k
for k in range(1,7):
    def step(S,a,k=k):
        out={0}
        for q in S:
            if q==0 and a=='1': out.add(1)
            if 1<=q<k: out.add(q+1)
        return frozenset(out)
    assert minimal_size(frozenset({0}),step,lambda S,k=k: k in S,'01')==2**k
# even number of 0s and odd number of 1s: 4 states
assert minimal_size((0,0),lambda s,a:(s[0]^(a=='0'),s[1]^(a=='1')),lambda s:s==(0,1),'01')==4
# contains ab: 3 states
assert minimal_size(0,lambda s,a:2 if s==2 else (1 if a=='a' else (2 if s==1 else 0)),lambda s:s==2,'ab')==3
# no two consecutive 1s: 3 states (including dead)
assert minimal_size('A',lambda s,a:{('A','0'):'A',('A','1'):'B',('B','0'):'A',('B','1'):'D'}.get((s,a),'D'),lambda s:s in 'AB','01')==3
# multiples of m in binary: m states for m odd
for m in (3,5,7,9):
    assert minimal_size(0,lambda r,a,m=m:(2*r+int(a))%m,lambda r:r==0,'01')==m
