def inc(s):
    tape={i:c for i,c in enumerate(s)}; pos=0; st='r'
    while True:
        c=tape.get(pos,'_')
        if st=='r':
            if c in '01': pos+=1
            else: pos-=1; st='c'
        else:
            if c=='1': tape[pos]='0'; pos-=1
            else: tape[pos]='1'; break
    lo=min(k for k in tape if tape[k]!='_'); hi=max(k for k in tape if tape[k]!='_')
    return ''.join(tape[k] for k in range(lo,hi+1))
assert inc('1011')=='1100' and inc('111')=='1000'
for n in range(512): assert int(inc(bin(n)[2:]),2)==n+1

