d={('q0','0'):('X','R','q1'),('q0','Y'):('Y','R','q3'),('q0','_'):('_','R','acc'),
   ('q1','0'):('0','R','q1'),('q1','Y'):('Y','R','q1'),('q1','1'):('Y','L','q2'),
   ('q2','0'):('0','L','q2'),('q2','Y'):('Y','L','q2'),('q2','X'):('X','R','q0'),
