def run(w):
    tape=dict(enumerate(w)); pos=0; st='q0'; n=0
    while st not in ('acc','rej'):
        k=(st,tape.get(pos,'_'))
        if k not in d: st='rej'; n+=1; break
        a,m,st=d[k]; tape[pos]=a; pos+=1 if m=='R' else -1; n+=1
    return st=='acc', n
